import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

/**
 * Generates app/tokens.css (a Tailwind v4 @theme) from design/tokens.json, the single source of
 * design values (plan §3.2). Run `pnpm tokens` after editing the JSON; `pnpm tokens:check` (CI)
 * fails if the generated file is out of date.
 */
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const tokensPath = path.join(root, "design/tokens.json");
const outPath = path.join(root, "app/tokens.css");

const quoteFamily = (name) => (/^[a-z-]+$/.test(name) ? name : `"${name}"`);

export function buildTokensCss(tokens) {
  const theme = [];
  const add = (name, value) => theme.push(`  --${name}: ${value};`);

  theme.push("  /* Colours: bg-*, text-*, border-*, ring-* (e.g. bg-primary, text-ink-muted) */");
  for (const [name, token] of Object.entries(tokens.color)) add(`color-${name}`, token.value);

  theme.push("", "  /* Fonts: font-sans (default), font-bangla, font-display */");
  for (const [name, token] of Object.entries(tokens.font)) add(`font-${name}`, token.value.map(quoteFamily).join(", "));

  theme.push("", "  /* Type scale: text-caption … text-display (size + line height) */");
  for (const [name, token] of Object.entries(tokens.text)) {
    add(`text-${name}`, token.size);
    add(`text-${name}--line-height`, token.lineHeight);
  }

  theme.push("", "  /* Radius: rounded-input, rounded-card, rounded-sheet */");
  for (const [name, token] of Object.entries(tokens.radius)) add(`radius-${name}`, token.value);

  theme.push("", "  /* Elevation: shadow-card, shadow-overlay */");
  for (const [name, token] of Object.entries(tokens.shadow)) add(`shadow-${name}`, token.value);

  theme.push("", "  /* Motion easing: ease-fast, ease-sheet */");
  for (const [name, token] of Object.entries(tokens.motion)) add(`ease-${name}`, token.easing);

  const root = [];
  root.push("  /* Motion durations: duration-(--motion-fast), duration-(--motion-sheet) */");
  for (const [name, token] of Object.entries(tokens.motion)) root.push(`  --motion-${name}: ${token.duration};`);
  root.push("", "  /* Line heights for running text */");
  for (const [name, token] of Object.entries(tokens.lineHeight)) root.push(`  --leading-${name}: ${token.value};`);

  return [
    "/* Generated by scripts/build-tokens.mjs from design/tokens.json. Do not edit; run `pnpm tokens`. */",
    "",
    "@theme {",
    ...theme,
    "}",
    "",
    ":root {",
    ...root,
    "}",
    "",
  ].join("\n");
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const css = buildTokensCss(JSON.parse(fs.readFileSync(tokensPath, "utf8")));
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, "utf8") : "";
    if (current !== css) {
      console.error("app/tokens.css is out of date with design/tokens.json. Run `pnpm tokens` and commit the result.");
      process.exit(1);
    }
    console.log("app/tokens.css is up to date.");
  } else {
    fs.writeFileSync(outPath, css);
    console.log(`Generated ${path.relative(root, outPath)}`);
  }
}
